<template><div class="page"><div class="hero"><div><div class="eyebrow">WORKSPACE / TASKS</div><h2>任务管理</h2><p>集中创建、监控和管理问卷自动化任务</p></div><el-button class="create-btn" type="primary" size="large" @click="dialog=true">＋ 创建新任务</el-button></div><div class="stats"><div class="stat"><span>全部任务</span><strong>{{store.tasks.length}}</strong></div><div class="stat blue"><span>进行中</span><strong>{{activeCount}}</strong></div><div class="stat green"><span>已完成</span><strong>{{doneCount}}</strong></div><div class="stat orange"><span>成功提交</span><strong>{{successCount}}</strong></div></div><div class="card table-card"><el-empty v-if="!store.tasks.length" description="还没有任务，点击右上角开始创建"/><el-table v-else :data="store.tasks" stripe><el-table-column prop="task_id" label="任务 ID" min-width="240"/><el-table-column prop="url" label="问卷 URL" show-overflow-tooltip/><el-table-column label="进度" width="220"><template #default="{row}"><el-progress :percentage="row.progress" :status="row.status==='failed'?'exception':row.status==='completed'?'success':undefined"/></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag round :type="row.status==='completed'?'success':row.status==='failed'?'danger':'primary'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link type="primary" @click="$router.push('/tasks/'+row.task_id)">查看</el-button><el-button link type="danger" @click="remove(row.task_id)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" title="创建新任务" width="680px" destroy-on-close><el-steps :active="step" finish-status="success" simple><el-step title="输入 URL"/><el-step title="预览问卷"/><el-step title="配置提交"/></el-steps><el-form v-if="step===0" class="wizard-form" :model="form"><el-form-item label="问卷 URL"><el-input v-model="form.url" placeholder="https://..."/></el-form-item><el-form-item><el-checkbox v-model="form.use_ai" :disabled="!ai.available">使用 AI 识别反向题（需先配置 AI）</el-checkbox><el-link v-if="!ai.available" type="primary" :underline="false" @click="$router.push('/settings/ai')">设置 AI</el-link><p class="ai-hint">启用后，系统将使用 AI 模型智能识别反向题和量表选项方向</p></el-form-item><el-button type="primary" :loading="loading" @click="analyze">解析问卷</el-button></el-form><div v-else-if="step===1"><el-alert title="问卷解析成功" type="success" show-icon/><p>共 {{questionnaire?.total_questions}} 道题，量表题 {{questionnaire?.scale_questions}} 道</p><el-table :data="questionnaire?.questions" max-height="260"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="label" label="题目"/><el-table-column prop="type" label="题型" width="100"/><el-table-column label="是量表题" width="90" align="center"><template #default="{row}">{{ row.is_scale ? '是' : '否' }}</template></el-table-column><el-table-column label="反向题" width="90" align="center"><template #default="{row}">{{ row.is_scale ? (row.is_reverse ? '是' : '否') : '-' }}</template></el-table-column><el-table-column label="检测方法" width="105"><template #default="{row}"><el-tag v-if="row.detection_method" size="small" :type="row.detection_method==='ai'?'primary':'info'">{{row.detection_method==='ai'?'AI':'关键词'}}</el-tag><span v-else>-</span></template></el-table-column><el-table-column label="积极值" width="105"><template #default="{row}">{{row.is_scale&&row.positive_values?.length?`[${row.positive_values.join(',')}]`:'-'}}</template></el-table-column><el-table-column label="消极值" width="105"><template #default="{row}">{{row.is_scale&&row.negative_values?.length?`[${row.negative_values.join(',')}]`:'-'}}</template></el-table-column></el-table><QuestionPreview v-if="questionnaire" :questions="questionnaire.questions" /><el-button @click="step=0">上一步</el-button><el-button type="primary" @click="step=2">下一步</el-button></div><el-form v-else class="wizard-form" :model="form"><el-form-item label="提交数量"><el-input-number v-model="form.count" :min="1" :max="1000"/></el-form-item><el-form-item label="模式"><el-radio-group v-model="form.mode"><el-radio value="random">随机</el-radio><el-radio value="high_reliability">高可靠性</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.mode==='high_reliability'" label="态度"><el-radio-group v-model="form.attitude"><el-radio value="positive">积极</el-radio><el-radio value="negative">消极</el-radio></el-radio-group></el-form-item><el-alert v-if="form.use_ai && questionnaire" type="info" :closable="false" show-icon :title="`AI ???? ${questionnaire.scale_questions} ????`"><template #default><div>???????????/?????????????????/??????</div></template></el-alert><div v-if="form.mode === 'high_reliability' && (form.attitude === 'positive' || form.attitude === 'negative')" class="variation-option"><el-checkbox v-model="form.add_variation">加入随机答案生成</el-checkbox><p class="variation-hint">勾选后，会在保证量表题积极或消极倾向的情况下包含随机答案，使答案没有那么极端。</p><el-form-item v-if="form.add_variation" label="随机答案比例" class="ratio-field"><el-input-number v-model="form.variation_ratio" :min="1" :max="30" :step="1" /><span class="ratio-unit">%</span></el-form-item></div><div><el-button @click="step=1">上一步</el-button><el-button type="primary" :loading="loading" @click="create">创建并开始任务</el-button></div></el-form></el-dialog></div></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useTaskStore } from '@/stores/task'
import { useAiStore } from '@/stores/ai'
import { analyzeQuestionnaire } from '@/api/questionnaire'
import { useRouter } from 'vue-router'
import type { Questionnaire } from '@/types'
import QuestionPreview from '@/components/Questionnaire/QuestionPreview.vue'

const store = useTaskStore()
const ai = useAiStore()
const router = useRouter(); const dialog=ref(false); const step=ref(0); const loading=ref(false); const questionnaire=ref<Questionnaire>();
const form=reactive<any>({url:'',count:10,mode:'random',attitude:'positive',use_ai:localStorage.getItem('questionnaire_use_ai')==='true',add_variation:false,variation_ratio:15})
watch(() => form.use_ai, value => localStorage.setItem('questionnaire_use_ai', String(value)))
const activeCount=computed(()=>store.tasks.filter(t=>t.status==='processing'||t.status==='pending').length); const doneCount=computed(()=>store.tasks.filter(t=>t.status==='completed').length); const successCount=computed(()=>store.tasks.reduce((n,t)=>n+t.submitted,0));
const statusText=(s:string)=>({pending:'等待中',processing:'进行中',completed:'已完成',failed:'失败'}[s]||s)
onMounted(() => { store.fetchList(); ai.fetchConfig() })

const remove = async (id: string) => {
  try {
    await ElMessageBox.confirm('确定删除该任务吗？', '确认')
    await store.remove(id)
    ElMessage.success('已删除')
  } catch {
    // 用户取消删除时保持当前列表不变。
  }
}
const analyze=async()=>{if(!form.url)return ElMessage.warning('请输入问卷 URL');loading.value=true;try{questionnaire.value=(await analyzeQuestionnaire(form.url, form.use_ai)).data.data;step.value=1}catch{ElMessage.error('解析失败')}finally{loading.value=false}}
const create=async()=>{loading.value=true;try{const t=await store.create({url:form.url,count:form.count,mode:form.mode,config:form.mode==='high_reliability'?{attitude:form.attitude,add_variation:form.add_variation,variation_ratio:form.variation_ratio / 100}:undefined});dialog.value=false;step.value=0;await router.push('/tasks/'+t.task_id)}catch{ElMessage.error('创建任务失败')}finally{loading.value=false}}
</script>
<style scoped>.hero{display:flex;justify-content:space-between;align-items:center;padding:28px 30px;border-radius:16px;background:linear-gradient(110deg,#1d3263,#4263b8);color:#fff;box-shadow:0 10px 30px #334e9630}.eyebrow{font-size:11px;letter-spacing:2px;opacity:.65}.hero h2{font-size:27px;margin:7px 0}.hero p{margin:0;color:#d6e2ff}.create-btn{border:0;background:#fff;color:#3454bd}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.stat{padding:18px 20px;border-radius:12px;background:#fff;box-shadow:0 4px 18px #1f29370b;border-left:4px solid #7c8ca8}.stat span{display:block;color:#8b98aa;font-size:13px}.stat strong{display:block;font-size:25px;margin-top:8px}.stat.blue{border-color:#5d7df2}.stat.green{border-color:#35b98a}.stat.orange{border-color:#f3a43b}.table-card{padding:10px 18px}.wizard-form{padding:28px 20px}.el-steps{margin:15px 0 25px}@media(max-width:800px){.stats{grid-template-columns:repeat(2,1fr)}.hero{padding:22px}.page{padding:15px}} .variation-hint{margin:6px 0 0 24px;color:#8792a6;font-size:12px;line-height:1.5}.variation-option{margin-top:8px}.ratio-field{margin:14px 0 0 24px}.ratio-unit{margin-left:8px;color:#657085}</style>
